import type { Context } from '@deepseek-ai/cordis'

const SOURCE = '@takomitkm/dsh-genshin-bg'

const STYLE = `
[data-genshin-bg] {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
  background: #000;
}
[data-genshin-bg] iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  display: block;
}
`

export const inject: string[] = []

export function apply(ctx: Context): void {
  let styleEl: HTMLStyleElement | undefined
  let root: HTMLDivElement | undefined

  ctx.effect(() => {
    styleEl = document.createElement('style')
    styleEl.dataset.plugin = SOURCE
    styleEl.textContent = STYLE
    document.head.appendChild(styleEl)

    root = document.createElement('div')
    root.dataset.genshinBg = ''
    root.setAttribute('aria-hidden', 'true')

    const iframe = document.createElement('iframe')
    iframe.src = '/genshin-bg/index.html'
    iframe.setAttribute('frameborder', '0')
    iframe.setAttribute('scrolling', 'no')
    iframe.title = 'Genshin ambient background'
    root.appendChild(iframe)

    ;(document.body ?? document.documentElement).prepend(root)

    return () => {
      root?.remove()
      root = undefined
      styleEl?.remove()
      styleEl = undefined
    }
  }, 'genshin-bg: ambient loop backdrop')
}
